## Code Example
```javascript
class SpaceSaving {
  constructor(k){ this.k=k; this.map=new Map(); this.counterHeap=[]; }
  update(x){ if(this.map.has(x)){ this.map.get(x).cnt++; return; }
    if(this.map.size < this.k){ this.map.set(x,{cnt:1}); return; }
    // replace min counter item
    let minKey = null, minCnt = Infinity;
    for(const [key,v] of this.map){ if(v.cnt < minCnt){ minCnt=v.cnt; minKey=key; } }
    this.map.delete(minKey);
    this.map.set(x,{cnt:minCnt+1});
  }
  topK(){ // shallow: return current keys with counts
    return Array.from(this.map.entries()).sort((a,b)=>b[1].cnt-a[1].cnt).map(([k,v])=>({key:k,count:v.cnt}));
  }
}
```

## Why This Is Asked
Tests ability to design incremental geometry data structures, reason about dominance, and assess batch-update trade-offs.

## Key Concepts
- Pareto frontier maintenance
- Batch incremental updates
- Monotone frontier properties (x increasing, y decreasing)
- Trade-offs: update time vs rebuild cost

## Code Example
```javascript
// Pseudocode sketch: merge batch into frontier
function insertBatch(frontier, batch){
  batch.sort((a,b)=> a.x-b.x);
  // prune intra-batch dominated
  let filtered=[]; let maxY=-Infinity;
  for(let p of batch){ if(p.y>maxY){ filtered.push(p); maxY=p.y; } }
  // merge with frontier (frontier: sorted by x, y strictly decreasing)
  let i=0,j=0; let newFrontier=[];
  while(i<frontier.length || j<filtered.length){
    let a = frontier[i], b = filtered[j];
    if(!a) { newFrontier.push(...filtered.slice(j)); break; }
    if(!b) { newFrontier.push(...frontier.slice(i)); break; }
    if(a.x < b.x){ newFrontier.push(a); i++; }
    else if(b.x < a.x){ newFrontier.push(b); j++; }
    else { // equal x, keep larger y
      if(a.y > b.y){ newFrontier.push(a); i++; j++; }
      else { newFrontier.push(b); i++; j++; }
    }
  }
  // optional prune to maintain y-decreasing property
  return pruneFrontier(newFrontier);
}
```

## Why This Is Asked
